import { useCallback, useEffect, useState } from 'react'
import type { PaymentMethod as PaymentMethodType } from '@shared/validations'
import { ShoppingCart, User } from 'lucide-react'
import { useCartStore } from '../store'
import { PartsSearch } from '../components/PartsSearch'
import { CartDisplay } from '../components/CartDisplay'
import { PosSection } from '../components/PosSection'
import { PosSidebar } from '../components/PosSidebar'
import { CustomerSelector, type CustomerSelectorItem } from '@/features/customers/components/CustomerSelector'
import { PaymentDialog } from '../components/PaymentDialog'
import { submitCheckout, parseCheckoutSuccess } from '../services/checkout'

// ============================================================================
// Component — POS Page
// Premium dark layout:
//   • Left column: vertical stack of three glass sections
//       1. Customer (selector)
//       2. Add Items (search + barcode + special form)
//       3. Cart (line items table)
//   • Right sidebar: customer card + running totals + Pay button (sticky)
// ============================================================================

export function PosPage() {
  const customerId = useCartStore((s) => s.customerId)
  const setCustomer = useCartStore((s) => s.setCustomer)
  const startCheckout = useCartStore((s) => s.startCheckout)
  const finishCheckout = useCartStore((s) => s.finishCheckout)
  const failCheckout = useCartStore((s) => s.failCheckout)
  const getCheckoutPayload = useCartStore((s) => s.getCheckoutPayload)
  const lineItemCount = useCartStore((s) => s.lineItems.length)

  // Handle checkout submission
  const handleCheckout = useCallback(
    async (method: PaymentMethodType) => {
      startCheckout()

      try {
        const payload = getCheckoutPayload()
        // Override payment method from the form selection
        const checkoutPayload = { ...payload, paymentMethod: method }

        const response = await submitCheckout(checkoutPayload)
        const success = parseCheckoutSuccess(response)
        finishCheckout(success)
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error during checkout'
        failCheckout(message)
      }
    },
    [startCheckout, finishCheckout, failCheckout, getCheckoutPayload]
  )

  const [paymentOpen, setPaymentOpen] = useState(false)

  // ── Cached selected customer (for sidebar display) ──
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<CustomerSelectorItem | null>(null)

  useEffect(() => {
    if (!customerId) {
      setSelectedCustomerCache(null)
      return
    }

    let cancelled = false
    async function fetchCustomer() {
      try {
        const response = await fetch('/api/customers')
        if (response.ok) {
          const data = await response.json()
          if (!cancelled) {
            const found = data.customers?.find((c: CustomerSelectorItem) => c.id === customerId)
            setSelectedCustomerCache(found ?? null)
          }
        }
      } catch {
        // Silently fail
      }
    }
    fetchCustomer()
    return () => { cancelled = true }
  }, [customerId])

  return (
    <div className="dashboard-bg -m-6 min-h-full p-5 sm:p-7 lg:p-8">
      {/* Atmospheric glow orbs (subtle background motion) */}
      <div className="glow-orb glow-orb-cyan" aria-hidden />
      <div className="glow-orb glow-orb-violet" aria-hidden />

      {/* Page header */}
      <header className="relative z-[1] mb-6 animate-hero-reveal">
        <div className="mb-2 flex items-center gap-2">
          <span className="text-[10px] font-bold uppercase tracking-[.2em] text-cyan-400/70">
            Point of Sale
          </span>
          <span className="h-px w-8 bg-gradient-to-r from-cyan-400/60 to-transparent" />
        </div>
        <h1 className="bg-gradient-to-r from-cyan-300 via-blue-300 to-violet-300 bg-clip-text text-3xl font-extrabold tracking-tight text-transparent sm:text-4xl sm:leading-none">
          New Sale
        </h1>
        <p className="mt-2 text-sm text-muted-foreground/80">
          Scan, search, and check out — totals update live on the right.
        </p>
        <div className="mt-3 h-px w-40 animated-underline" aria-hidden />
      </header>

      {/* Main layout: left stack + right sidebar */}
      <div className="relative z-[1] flex gap-6">
        {/* Left column — vertical stack of three sections */}
        <div className="flex-1 min-w-0 flex flex-col gap-4 stagger-children">
          <PosSection
            icon={User}
            title="Customer"
            subtitle={customerId ? 'Customer attached' : 'Walk-in or pick a customer'}
          >
            <CustomerSelector
              customerId={customerId}
              onSelect={(id) => setCustomer(id)}
            />
          </PosSection>

          <PosSection
            icon={ShoppingCart}
            title="Add Items"
            subtitle="Scan barcode or search by name"
          >
            <PartsSearch />
          </PosSection>

          <PosSection
            icon={ShoppingCart}
            title="Cart"
            subtitle={lineItemCount === 0 ? 'No items yet' : `${lineItemCount} ${lineItemCount === 1 ? 'item' : 'items'} in cart`}
            badge={
              lineItemCount > 0 ? (
                <span className="inline-flex items-center justify-center min-w-[1.5rem] h-6 px-2 rounded-full text-[11px] font-bold tabular-nums bg-cyan-500/15 text-cyan-300/95 ring-1 ring-cyan-400/30">
                  {lineItemCount}
                </span>
              ) : null
            }
          >
            <CartDisplay />
          </PosSection>
        </div>

        {/* Right column — sticky sidebar with customer + totals + Pay */}
        <PosSidebar
          selectedCustomer={selectedCustomerCache}
          hasCustomer={!!customerId}
          onPay={() => setPaymentOpen(true)}
        />
      </div>

      {/* Payment dialog */}
      <PaymentDialog
        open={paymentOpen}
        onClose={() => setPaymentOpen(false)}
        onCheckout={handleCheckout}
      />
    </div>
  )
}

import { useCallback, useEffect, useRef, useState } from 'react'
import { Input } from '@/components/ui/input'

// ============================================================================
// Types
// ============================================================================

/** Compact customer shape returned by GET /customers (search response). */
export interface CustomerSelectorItem {
  id: string
  displayName: string
  type: 'private' | 'company'
  email?: string | null
  phone?: string | null
}

interface CustomerSearchResponse {
  customers: CustomerSelectorItem[]
}

// ============================================================================
// Props
// ============================================================================

export interface CustomerSelectorProps {
  /** Currently selected customer id (null = walk-in/anonymous). */
  customerId?: string | null
  /** Called when user selects a customer or chooses walk-in. */
  onSelect: (id: string | null) => void
  /** Whether a customer must be selected (walk-in not allowed). */
  required?: boolean
}

// ============================================================================
// Debounce hook — minimal inline implementation (250ms)
// ============================================================================

function useDebounce<T>(value: T, delayMs: number): T {
  const [debouncedValue, setDebouncedValue] = useState<T>(value)

  useEffect(() => {
    const timer = setTimeout(() => setDebouncedValue(value), delayMs)
    return () => clearTimeout(timer)
  }, [value, delayMs])

  return debouncedValue
}

// ============================================================================
// Component — Customer Selector (autocomplete input)
// ============================================================================

export function CustomerSelector({
  customerId = null,
  onSelect,
  required = false,
}: CustomerSelectorProps) {
  // Search state
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<CustomerSelectorItem[]>([])
  const [isLoading, setIsLoading] = useState(false)
  const [isOpen, setIsOpen] = useState(false)
  const [highlightIndex, setHighlightIndex] = useState(-1)

  // Debounced query (250ms delay before API call)
  const debouncedQuery = useDebounce(query, 250)

  // Refs for keyboard navigation and click-outside detection
  const inputRef = useRef<HTMLInputElement>(null)
  const dropdownRef = useRef<HTMLDivElement>(null)

  // ── Fetch customers on debounced query change ────────────────────

  useEffect(() => {
    // No search term → clear results, close dropdown
    if (!debouncedQuery || debouncedQuery.trim() === '') {
      setResults([])
      setIsOpen(false)
      return
    }

    let cancelled = false

    async function fetchCustomers() {
      setIsLoading(true)
      try {
        const response = await fetch(`/api/customers?search=${encodeURIComponent(debouncedQuery.trim())}`)
        if (response.ok) {
          const data: CustomerSearchResponse = await response.json()
          if (!cancelled) {
            setResults(data.customers.slice(0, 20))
            setIsOpen(true)
            setHighlightIndex(-1)
          }
        } else {
          if (!cancelled) {
            setResults([])
            setIsOpen(false)
          }
        }
      } catch {
        // Silently fail — walk-in is always available
        if (!cancelled) {
          setResults([])
          setIsOpen(false)
        }
      } finally {
        if (!cancelled) {
          setIsLoading(false)
        }
      }
    }

    fetchCustomers()
    return () => { cancelled = true }
  }, [debouncedQuery])

  // ── Click-outside handler — close dropdown when clicking outside ─

  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (
        dropdownRef.current && !dropdownRef.current.contains(event.target as Node) &&
        inputRef.current && !inputRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false)
      }
    }

    document.addEventListener('mousedown', handleClickOutside)
    return () => document.removeEventListener('mousedown', handleClickOutside)
  }, [])

  // ── Select a customer ────────────────────────────────────────────

  const handleSelectCustomer = useCallback((id: string | null) => {
    onSelect(id)
    setIsOpen(false)
    if (id === null) {
      // Reset to walk-in — clear input
      setQuery('')
      setResults([])
    }
  }, [onSelect])

  // ── Keyboard navigation ──────────────────────────────────────────

  const handleKeyDown = useCallback((e: React.KeyboardEvent<HTMLInputElement>) => {
    if (!isOpen || results.length === 0) return

    switch (e.key) {
      case 'ArrowDown':
        e.preventDefault()
        setHighlightIndex((prev) => Math.min(prev + 1, results.length - 1))
        break

      case 'ArrowUp':
        e.preventDefault()
        setHighlightIndex((prev) => Math.max(prev - 1, 0))
        break

      case 'Enter':
        e.preventDefault()
        if (highlightIndex >= 0 && highlightIndex < results.length) {
          handleSelectCustomer(results[highlightIndex].id)
        } else if (results.length === 1) {
          // Auto-select single result
          handleSelectCustomer(results[0].id)
        }
        break

      case 'Escape':
        e.preventDefault()
        setIsOpen(false)
        inputRef.current?.blur()
        break
    }
  }, [isOpen, results, highlightIndex, handleSelectCustomer])

  // ── Render helpers ───────────────────────────────────────────────

  return (
    <div className="space-y-3">
        {/* Label */}
        <label htmlFor="customer-search" className="text-[11px] font-semibold uppercase tracking-wider text-muted-foreground/80 block">
          Customer {required && <span className="text-amber-300/90">*</span>}
        </label>

        {/* Search input with dropdown */}
        <div ref={dropdownRef} className="relative">
          <Input
            id="customer-search"
            ref={inputRef}
            type="search"
            placeholder="Search customers..."
            value={query}
            onChange={(e) => {
              setQuery(e.target.value)
              setIsOpen(true)
              setHighlightIndex(-1)
            }}
            onFocus={() => {
              if (results.length > 0) setIsOpen(true)
            }}
            onKeyDown={handleKeyDown}
            className="w-full bg-white/[.04] border-white/10 focus:border-cyan-400/50 focus:ring-cyan-400/30"
          />

          {/* Dropdown */}
          {isOpen && results.length > 0 && (
            <div className="absolute z-50 w-full mt-1 bg-slate-900/95 border border-white/10 rounded-md shadow-2xl backdrop-blur-xl max-h-64 overflow-y-auto">
              {/* Loading indicator */}
              {isLoading && (
                <div className="px-3 py-2 text-sm text-muted-foreground">Searching...</div>
              )}

              {/* Results list */}
              {!isLoading && results.map((customer, index) => (
                <button
                  key={customer.id}
                  type="button"
                  onClick={() => handleSelectCustomer(customer.id)}
                  onMouseEnter={() => setHighlightIndex(index)}
                  className={`w-full text-left px-3 py-2 text-sm transition-colors ${
                    index === highlightIndex
                      ? 'bg-accent text-accent-foreground'
                      : customerId === customer.id
                        ? 'bg-muted/50 font-medium'
                        : 'hover:bg-accent hover:text-accent-foreground'
                  }`}
                >
                  <div className="font-medium truncate">{customer.displayName}</div>
                  <div className="flex gap-3 text-xs text-muted-foreground mt-0.5">
                    {customer.email && (
                      <span className="truncate">{customer.email}</span>
                    )}
                    {customer.phone && (
                      <span className="truncate">{customer.phone}</span>
                    )}
                  </div>
                </button>
              ))}

              {/* No results within the loaded set */}
              {!isLoading && results.length === 0 && query.trim() !== '' && (
                <div className="px-3 py-2 text-sm text-muted-foreground">No customers found</div>
              )}
            </div>
          )}

          {/* Empty state hint — shown when input is focused but no results */}
          {isOpen && query.trim() !== '' && !isLoading && results.length === 0 && (
            <div className="absolute z-50 w-full mt-1 bg-slate-900/95 border border-white/10 rounded-md shadow-2xl backdrop-blur-xl px-3 py-2 text-sm text-muted-foreground">
              No customers found
            </div>
          )}
        </div>

        {/* Walk-in option — always visible */}
        <button
          type="button"
          onClick={() => handleSelectCustomer(null)}
          className={`w-full justify-start text-sm px-3 py-2 rounded-md border transition-all ${
            customerId === null
              ? 'bg-gradient-to-r from-cyan-500/15 to-violet-500/15 text-cyan-100 border-cyan-400/40 shadow-[0_0_18px_rgba(34,211,238,.18)]'
              : 'border-dashed border-white/15 text-muted-foreground/80 hover:bg-white/[.04] hover:text-foreground hover:border-white/25'
          }`}
        >
          Walk-in (anonymous) {required && customerId === null && <span className="text-xs opacity-75 ml-1">(no customer)</span>}
        </button>

        {/* Live-region announcement for screen readers (also keeps the
            "anonymous sale" text discoverable for tests). */}
        {customerId === null && (
          <p className="sr-only" role="status">
            Anonymous sale — no customer attached
          </p>
        )}
      </div>
  )
}

/**
 * Customers — Frontend types.
 */

// ---------------------------------------------------------------------------
// Customer shapes (mirroring backend DTOs)
// ---------------------------------------------------------------------------

/** Compact customer shape for dropdown selectors. */
export interface CustomerSelectorItem {
  /** Unique customer identifier */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
}

/** Full customer detail returned by CRUD endpoints. */
export interface CustomerDetail {
  /** Unique customer identifier (client-generated UUID) */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
  /** First name — required for private customers */
  firstName?: string
  /** Last name — required for private customers */
  lastName?: string
  /** Company name — required for company customers */
  companyName?: string
  /** VAT ID — for company customers */
  vatId: string | null
  /** Phone number (loose validation: min 1, max 50 chars) */
  phone: string | null
  /** Email address (loose validation: min 1, max 50 chars) */
  email: string | null
  /** Street name */
  street: string | null
  /** Building/house number */
  number: string | null
  /** Apartment/unit number */
  bus: string | null
  /** Postal / ZIP code */
  postalCode: string | null
  /** City */
  city: string | null
  /** Country code (default: 'BE') */
  country: string
  /** Notification preference — sms or email */
  notificationPreference: 'sms' | 'email' | null
  // Index signature required by DataTable<T extends Record<string, unknown>>
  [key: string]: unknown
}

/** Display name computed from customer type and fields. */
export function getDisplayName(customer: CustomerDetail): string {
  return customer.type === 'private'
    ? [customer.firstName, customer.lastName].filter(Boolean).join(' ').trim() || ''
    : (customer.companyName ?? '')
}

// ---------------------------------------------------------------------------
// Pagination shapes
// ---------------------------------------------------------------------------

/** Paginated response from the management list endpoint. */
export interface CustomerPaginatedResponse {
  customers: CustomerDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Customer Detail Panel — Activity types
// ---------------------------------------------------------------------------

/** Sale record for customer detail panel (from /sales?customerId=...) */
export interface CustomerSale {
  id: string
  saleNumber: string
  sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
  sourceId: string | null
  status: 'completed' | 'voided'
  subtotalNet: number
  vatTotal: number
  totalGross: number
  createdAt: number // epoch ms
}

/** Line item within a sale */
export interface SaleLineItem {
  id: string
  description: string
  quantity: number
  unitPriceNet: number
  lineNetTotal: number
  vatRateBps: number
  lineVatTotal: number
  lineGrossTotal: number
}

/** Payment record for a sale */
export interface SalePayment {
  id: string
  method: 'cash' | 'card' | 'bank_transfer'
  amount: number // cents
  allocatedAmount: number // cents
}

/** Enriched sale with line items and payments (fetched via /sales/:id) */
export interface CustomerSaleDetail {
  sale: CustomerSale
  lineItems: SaleLineItem[]
  payments: SalePayment[]
}

/** Bicycle owned by customer (from /bicycles?customerId=...) */
export interface CustomerBicycle {
  id: string
  source: 'inventory' | 'customer_owned'
  brand: string
  model: string
  year: number | null
  color: string | null
  isLease: boolean
  status: string
}

/** Repair record for customer detail panel */
export interface CustomerRepair {
  id: string
  bicycleId: string
  status: 'intake' | 'in_progress' | 'on_hold' | 'ready' | 'completed' | 'cancelled'
  plannedDate: number | null // epoch ms
  pickupDate: number | null
  completedAt: number | null
  createdAt: number
  bicycleBrand: string
  bicycleModel: string
}

/** Customer order for detail panel (from /orders?customerId=...) */
export interface CustomerOrder {
  id: string
  orderNumber: string
  status: 'pending' | 'ordered' | 'ready' | 'fulfilled' | 'cancelled'
  totalPriceNet: number // cents
  expectedDeliveryDate: number | null
  createdAt: number // epoch ms (timestamp)
}

/** Line item within a customer order */
export interface CustomerOrderLineItem {
  id: string
  description: string
  quantity: number
  unitPriceNet: number
  lineNetTotal: number
  vatRateBps: number
  lineVatTotal: number
  lineGrossTotal: number
}

/** Payment history entry for a customer order */
export interface OrderPaymentEntry {
  id: string
  method: 'cash' | 'card' | 'bank_transfer'
  amount: number // cents
  allocatedAmount: number // cents
}

import crypto from 'crypto'
import { db } from '@/db/index.js'
import {
  customers,
  sales,
  quotes,
  repairs,
  customerOrders,
  backorders,
  invoices,
  bicycles,
  type Customer as DbCustomer
} from '@/db/schema.js'
import { and, asc, eq, sql } from 'drizzle-orm'
import { createCustomerSchema, updateCustomerSchema, type CreateCustomerInput, type UpdateCustomerInput } from '@shared/validations/customer.js'

// ---------------------------------------------------------------------------
// DTO shapes returned by the API (compact customer selector item)
// ---------------------------------------------------------------------------

/**
 * Compact customer shape for dropdown selectors.
 *
 * Only includes id, display name, and type — no PII exposed.
 */
export interface CustomerSelectorItem {
  /** Unique customer identifier */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
}

/** Response envelope for the customer list endpoint. */
export interface CustomerListResponse {
  customers: CustomerSelectorItem[]
}

/** Query parameters for the paginated/managed customer list. */
export interface CustomerListQuery {
  /** Search term — filters across displayName, email, and phone */
  search?: string
  /** Page number (1-indexed) */
  page?: number
  /** Items per page */
  pageSize?: number
}

/** Paginated response for the management list endpoint. */
export interface CustomerPaginatedResponse {
  customers: CustomerDetail[]
  totalItems: number
  currentPage: number
  pageSize: number
  totalPages: number
}

// ---------------------------------------------------------------------------
// Public API — Read operations
// ---------------------------------------------------------------------------

/**
 * Get all customers formatted as a compact list suitable for dropdown selectors.
 *
 * Display name is computed from domain fields:
 * - Private customers: "firstName lastName"
 * - Company customers: companyName
 *
 * @returns Customer selector items sorted by display name
 */
export async function getCustomerList(): Promise<CustomerListResponse> {
  const results = await listCustomers()

  return {
    customers: results.map(toSelectorItem)
  }
}

/**
 * Get paginated customer list with optional search filtering.
 *
 * Returns full CustomerDetail records suitable for the management view.
 * Search filters across display name, email, and phone fields.
 *
 * @param query - Optional search term, page number, and page size
 * @returns Paginated response with customers and pagination metadata
 */
export async function getCustomerListPaginated(
  query: CustomerListQuery = {}
): Promise<CustomerPaginatedResponse> {
  const { search, page = 1, pageSize = 25 } = query
  const offset = (page - 1) * pageSize

  // Build filter conditions for search
  let whereClause: ReturnType<typeof and> | undefined

  if (search && search.trim()) {
    const term = `%${search.trim()}%`
    whereClause = and(
      sql`LOWER(CONCAT(${customers.firstName}, ' ', ${customers.lastName}, ' ', ${customers.companyName}, ' ', ${customers.email}, ' ', ${customers.phone})) LIKE ${term.toLowerCase()}`
    )
  }

  // Get total count for pagination
  let totalCount = 0
  if (whereClause) {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(customers).where(whereClause)
    totalCount = count
  } else {
    const [{ count }] = await db.select({ count: sql<number>`count(*)` }).from(customers)
    totalCount = count
  }

  // Get paginated results
  let results: DbCustomer[]
  if (whereClause) {
    results = await db.select().from(customers).where(whereClause)
      .orderBy(
        asc(
          sql`CASE WHEN ${customers.type} = 'private' THEN ${customers.lastName} ELSE ${customers.companyName} END`
        )
      )
      .limit(pageSize)
      .offset(offset)
  } else {
    results = await db.select().from(customers)
      .orderBy(
        asc(
          sql`CASE WHEN ${customers.type} = 'private' THEN ${customers.lastName} ELSE ${customers.companyName} END`
        )
      )
      .limit(pageSize)
      .offset(offset)
  }

  const totalPages = Math.max(1, Math.ceil(totalCount / pageSize))

  return {
    customers: results.map(toCustomerDetail),
    totalItems: totalCount,
    currentPage: page,
    pageSize,
    totalPages
  }
}

// ---------------------------------------------------------------------------
// Repository layer — database access functions
// ---------------------------------------------------------------------------

/**
 * List all customers ordered by display name (lastName for private, companyName for company).
 *
 * Uses a CASE expression to sort privately by lastName and companies by companyName
 * in a single unified alphabetical order.
 *
 * @returns Array of customer records sorted alphabetically by display name
 */
async function listCustomers(): Promise<DbCustomer[]> {
  return db
    .select()
    .from(customers)
    .orderBy(
      asc(
        sql`CASE WHEN ${customers.type} = 'private' THEN ${customers.lastName} ELSE ${customers.companyName} END`
      )
    )
}

// ---------------------------------------------------------------------------
// Helpers — map between DB Customer and DTO shapes
// ---------------------------------------------------------------------------

/**
 * Map a Customer entity to the dropdown selector shape.
 */
function toSelectorItem(customer: DbCustomer): CustomerSelectorItem {
  const displayName = customer.type === 'private'
    ? [customer.firstName, customer.lastName].filter(Boolean).join(' ').trim() || ''
    : (customer.companyName ?? '')

  return {
    id: customer.id,
    displayName,
    type: customer.type
  }
}

// ---------------------------------------------------------------------------
// DTO shapes — full customer detail for create/edit responses
// ---------------------------------------------------------------------------

/** Full customer detail returned by CRUD endpoints. */
export interface CustomerDetail {
  /** Unique customer identifier (client-generated UUID) */
  id: string
  /** Human-readable name: "firstName lastName" for private, companyName for company */
  displayName: string
  /** 'private' or 'company' */
  type: 'private' | 'company'
  /** First name — required for private customers */
  firstName?: string
  /** Last name — required for private customers */
  lastName?: string
  /** Company name — required for company customers */
  companyName?: string
  /** VAT ID — for company customers */
  vatId: string | null
  /** Phone number (loose validation: min 1, max 50 chars) */
  phone: string | null
  /** Email address (loose validation: min 1, max 50 chars) */
  email: string | null
  /** Street name */
  street: string | null
  /** Building/house number */
  number: string | null
  /** Apartment/unit number */
  bus: string | null
  /** Postal / ZIP code */
  postalCode: string | null
  /** City */
  city: string | null
  /** Country code (default: 'BE') */
  country: string
}

/** Map a DB Customer to the full detail shape. */
function toCustomerDetail(customer: DbCustomer): CustomerDetail {
  const displayName = customer.type === 'private'
    ? [customer.firstName, customer.lastName].filter(Boolean).join(' ').trim() || ''
    : (customer.companyName ?? '')

  return {
    id: customer.id,
    displayName,
    type: customer.type,
    firstName: customer.firstName ?? undefined,
    lastName: customer.lastName ?? undefined,
    companyName: customer.companyName ?? undefined,
    vatId: customer.vatId,
    phone: customer.phone,
    email: customer.email,
    street: customer.street,
    number: customer.number,
    bus: customer.bus,
    postalCode: customer.postalCode,
    city: customer.city,
    country: customer.country
  }
}

// ---------------------------------------------------------------------------
// Error types
// ---------------------------------------------------------------------------

/** Thrown when a customer lookup by ID finds no matching record. */
export class CustomerNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Customer not found: ${id}`)
    this.name = 'CustomerNotFoundError'
  }
}

/** Thrown when delete is blocked because the customer has related records. */
export class DeleteBlockedError extends Error {
  constructor(
    public readonly id: string,
    message: string
  ) {
    super(message)
    this.name = 'DeleteBlockedError'
  }
}

// ---------------------------------------------------------------------------
// Public API — Write operations
// ---------------------------------------------------------------------------

/**
 * Create a new customer.
 *
 * Validates input against the create schema (type branching), generates a UUID
 * if not provided, and persists to the database. Returns full detail shape.
 */
/** Convert validated input to DB format — replaces undefined with null for nullable fields. */
function toDbCustomer(data: CreateCustomerInput): DbCustomer {
  return {
    id: data.id ?? crypto.randomUUID(),
    type: data.type,
    firstName: data.firstName ?? null,
    lastName: data.lastName ?? null,
    companyName: data.companyName ?? null,
    vatId: data.vatId ?? null,
    phone: data.phone ?? null,
    email: data.email ?? null,
    street: data.street ?? null,
    number: data.number ?? null,
    bus: data.bus ?? null,
    postalCode: data.postalCode ?? null,
    city: data.city ?? null,
    country: data.country ?? 'BE',
    notificationPreference: null,
  }
}

/** Convert validated update input to partial DB format — replaces undefined with null. */
function toDbUpdate(data: UpdateCustomerInput): Partial<DbCustomer> {
  const result: Partial<DbCustomer> = {}
  if (data.firstName !== undefined) result.firstName = data.firstName ?? null
  if (data.lastName !== undefined) result.lastName = data.lastName ?? null
  if (data.companyName !== undefined) result.companyName = data.companyName ?? null
  if (data.vatId !== undefined) result.vatId = data.vatId ?? null
  if (data.phone !== undefined) result.phone = data.phone ?? null
  if (data.email !== undefined) result.email = data.email ?? null
  if (data.street !== undefined) result.street = data.street ?? null
  if (data.number !== undefined) result.number = data.number ?? null
  if (data.bus !== undefined) result.bus = data.bus ?? null
  if (data.postalCode !== undefined) result.postalCode = data.postalCode ?? null
  if (data.city !== undefined) result.city = data.city ?? null
  if (data.country !== undefined) result.country = data.country ?? 'BE'
  return result
}

export async function createCustomer(input: CreateCustomerInput): Promise<CustomerDetail> {
  const validated = createCustomerSchema.parse(input)
  const dbData = toDbCustomer(validated)

  const created = await repoCreateCustomer(dbData)
  return toCustomerDetail(created)
}

/**
 * Look up a single customer by ID.
 *
 * Returns full detail shape or undefined if not found.
 */
export async function getCustomerById(id: string): Promise<CustomerDetail | undefined> {
  const result = await repoFindCustomerById(id)
  return result ? toCustomerDetail(result) : undefined
}

/**
 * Update an existing customer with partial data.
 *
 * Validates that at least one field is provided, then updates only the
 * specified fields. Returns the updated CustomerDetail.
 */
export async function updateCustomer(id: string, input: UpdateCustomerInput): Promise<CustomerDetail> {
  const validated = updateCustomerSchema.parse(input)
  const dbUpdates = toDbUpdate(validated)

  const updated = await repoUpdateCustomer(id, dbUpdates)
  return toCustomerDetail(updated)
}

/**
 * Delete a customer by ID.
 *
 * Blocks deletion if the customer has related records in any of:
 * sales, invoices, quotes, repairs (via bicycles), customerOrders, backorders.
 *
 * @returns true on successful delete
 * @throws CustomerNotFoundError if customer doesn't exist
 * @throws DeleteBlockedError if related records prevent deletion
 */
export async function deleteCustomer(id: string): Promise<boolean> {
  // Verify customer exists first
  const existing = await repoFindCustomerById(id)
  if (!existing) {
    throw new CustomerNotFoundError(id)
  }

  // Check for related records across all tables that reference customers
  const blockingRecords = await findBlockingReferences(id)

  if (blockingRecords.length > 0) {
    const tableNames = blockingRecords.map(r => r.table).join(', ')
    throw new DeleteBlockedError(
      id,
      `Cannot delete customer: related records exist in ${tableNames}`
    )
  }

  // Safe to delete — remove the customer record
  await repoDeleteCustomer(id)
  return true
}

// ---------------------------------------------------------------------------
// Repository layer — database access functions
// ---------------------------------------------------------------------------

/** Find a single customer by ID. */
async function repoFindCustomerById(id: string): Promise<DbCustomer | undefined> {
  const [result] = await db
    .select()
    .from(customers)
    .where(eq(customers.id, id))

  return result ?? undefined
}

/** Create a new customer record. */
async function repoCreateCustomer(data: DbCustomer): Promise<DbCustomer> {
  const [created] = await db
    .insert(customers)
    .values({ ...data })
    .returning()

  return created
}

/** Update specific fields on an existing customer. */
async function repoUpdateCustomer(id: string, updates: Partial<DbCustomer>): Promise<DbCustomer> {
  const [updated] = await db
    .update(customers)
    .set(updates)
    .where(eq(customers.id, id))
    .returning()

  if (!updated) throw new CustomerNotFoundError(id)

  return updated
}

/** Delete a customer by ID. */
async function repoDeleteCustomer(id: string): Promise<void> {
  await db
    .delete(customers)
    .where(eq(customers.id, id))
}

/** Check for any related records that would block deletion. */
interface BlockingReference {
  table: string
}

async function findBlockingReferences(customerId: string): Promise<BlockingReference[]> {
  const results: BlockingReference[] = []

  // Direct references to customers.id
  const [salesCount] = await db
    .select({ count: sql<number>`count(*)` })
    .from(sales)
    .where(eq(sales.customerId, customerId))
  if (salesCount.count > 0) results.push({ table: 'sales' })

  const [quotesCount] = await db
    .select({ count: sql<number>`count(*)` })
    .from(quotes)
    .where(eq(quotes.customerId, customerId))
  if (quotesCount.count > 0) results.push({ table: 'quotes' })

  const [ordersCount] = await db
    .select({ count: sql<number>`count(*)` })
    .from(customerOrders)
    .where(eq(customerOrders.customerId, customerId))
  if (ordersCount.count > 0) results.push({ table: 'customer_orders' })

  const [backordersCount] = await db
    .select({ count: sql<number>`count(*)` })
    .from(backorders)
    .where(eq(backorders.customerId, customerId))
  if (backordersCount.count > 0) results.push({ table: 'backorders' })

  const [invoicesCount] = await db
    .select({ count: sql<number>`count(*)` })
    .from(invoices)
    .where(eq(invoices.customerId, customerId))
  if (invoicesCount.count > 0) results.push({ table: 'invoices' })

  // Indirect reference via bicycles → repairs
  const bicycleIds = await db
    .select({ id: bicycles.id })
    .from(bicycles)
    .where(eq(bicycles.customerId, customerId))

  if (bicycleIds.length > 0) {
    const bicycleIdList = bicycleIds.map(b => b.id)
    const [repairCount] = await db
      .select({ count: sql<number>`count(*)` })
      .from(repairs)
      .where(eq(repairs.bicycleId, bicycleIdList[0])) // at least one repair exists
    if (repairCount.count > 0) results.push({ table: 'repairs' })
  }

  return results
}

import { Hono } from 'hono'
import {
  getCustomerList,
  type CustomerListResponse,
  getCustomerListPaginated,
  type CustomerListQuery
} from '../services/customer.service.js'
import { createCustomer, getCustomerById, updateCustomer, deleteCustomer, CustomerNotFoundError, DeleteBlockedError } from '../services/customer.service.js'
import { createCustomerSchema, updateCustomerSchema } from '@shared/validations/customer.js'

const customersRoutes = new Hono()

// ---------------------------------------------------------------------------
// GET /customers — List all customers for the POS customer selector dropdown.
//
// When called without query parameters, returns a compact shape:
// id, displayName (firstName+lastName or companyName), type.
// Suitable for populating a search/select dropdown component.
//
// When called with ?search= and/or ?page= parameters, returns full customer
// details with pagination — suitable for the management list view.
// ---------------------------------------------------------------------------

customersRoutes.get('/', async (c) => {
  const search = c.req.query('search')
  const page = c.req.query('page')
  const pageSize = c.req.query('pageSize')

  // If pagination or search params are present, return paginated full details
  if (search !== undefined || page !== undefined || pageSize !== undefined) {
    const query: CustomerListQuery = {}
    if (search !== undefined && search !== '') query.search = search
    if (page !== undefined) query.page = parseInt(page, 10)
    if (pageSize !== undefined) query.pageSize = parseInt(pageSize, 10)

    return c.json(await getCustomerListPaginated(query))
  }

  // Default: compact selector shape for POS dropdown consumers
  const result = await getCustomerList()
  return c.json(result as CustomerListResponse)
})

// ---------------------------------------------------------------------------
// GET /customers/:id — Get single customer detail
// ---------------------------------------------------------------------------

customersRoutes.get('/:id', async (c) => {
  const id = c.req.param('id')
  const customer = await getCustomerById(id)

  if (!customer) {
    return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
  }

  return c.json(customer)
})

// ---------------------------------------------------------------------------
// POST /customers — Create a new customer
// ---------------------------------------------------------------------------

customersRoutes.post('/', async (c) => {
  const input = await c.req.json()

  try {
    const validated = createCustomerSchema.parse(input)
    const customer = await createCustomer(validated)
    return c.json(customer, 201)
  } catch (err) {
    if (err instanceof SyntaxError) {
      // Invalid JSON body
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }
    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// PATCH /customers/:id — Update a customer (partial update allowed)
// ---------------------------------------------------------------------------

customersRoutes.patch('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    const input = await c.req.json()
    const validated = updateCustomerSchema.parse(input)
    const customer = await updateCustomer(id, validated)
    return c.json(customer)
  } catch (err) {
    if (err instanceof SyntaxError) {
      return c.json({ error: 'Invalid request body', code: 'VALIDATION_ERROR' }, 400)
    }

    if (err instanceof CustomerNotFoundError) {
      return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
    }

    // Zod validation error
    return c.json({ error: 'Validation failed', code: 'VALIDATION_ERROR' }, 400)
  }
})

// ---------------------------------------------------------------------------
// DELETE /customers/:id — Delete a customer (with blocking logic)
// ---------------------------------------------------------------------------

customersRoutes.delete('/:id', async (c) => {
  const id = c.req.param('id')

  try {
    await deleteCustomer(id)
    return c.json({ success: true })
  } catch (err) {
    if (err instanceof CustomerNotFoundError) {
      return c.json({ error: 'Customer not found', code: 'NOT_FOUND' }, 404)
    }

    if (err instanceof DeleteBlockedError) {
      return c.json({ error: err.message, code: 'CONFLICT' }, 409)
    }

    console.error('[DELETE /customers/:id] Unexpected error:', err)
    return c.json({ error: 'Internal server error', code: 'INTERNAL_ERROR' }, 500)
  }
})

export default customersRoutes

