}

// ============================================================================
// Helpers
// ============================================================================

function formatPrice(cents: number): string {
  const euros = (cents / 100).toFixed(2)
  return `€${euros}`
}

import { describe, it, expect, beforeEach } from 'vitest'
import app from '@/app.js'
import { db } from '@/db/index.js'
import { customers } from '@/db/schema.js'

describe('Customers Routes (flat service pattern)', () => {
  async function resetCustomers() {
    await db.delete(customers)
  }

  beforeEach(async () => {
    await resetCustomers()
  })

  describe('GET /api/customers', () => {
    it('should return 200 with empty array when no customers exist', async () => {
      const res = await app.request('/api/customers')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.customers).toEqual([])
    })

    it('should return private customers with display name (firstName + lastName)', async () => {
      await db.insert(customers).values([
        { id: 'cust-jan', type: 'private', firstName: 'Jan', lastName: 'Kowalski', notificationPreference: null as any },
        { id: 'cust-anna', type: 'private', firstName: 'Anna', lastName: 'Nowak', notificationPreference: null as any }
      ])

      const res = await app.request('/api/customers')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.customers).toHaveLength(2)

      // Verify response shape — compact for dropdown selector
      const customer = body.customers[0] as Record<string, unknown>
      expect(customer).toHaveProperty('id')
      expect(customer).toHaveProperty('displayName')
      expect(customer).toHaveProperty('type')

      // Verify display name format for private customers
      expect((customer.displayName as string)).toBe('Jan Kowalski')
    })

    it('should return company customers with companyName as display name', async () => {
      await db.insert(customers).values([
        { id: 'c1', type: 'company', companyName: 'TechSpółka Sp. z o.o.' },
        { id: 'cust-piotr', type: 'private', firstName: 'Piotr', lastName: 'Wiśniewski', notificationPreference: null as any }
      ])

      const res = await app.request('/api/customers')
      expect(res.status).toBe(200)

      const body = await res.json()
      expect(body.customers).toHaveLength(2)

      // Company customer should use companyName as displayName
      const companyCustomer = body.customers.find((c: Record<string, unknown>) => c.type === 'company')
      expect(companyCustomer?.displayName).toBe('TechSpółka Sp. z o.o.')
    })

