// ── Mock fetch for parts search ────────────────────────────────────

function mockFetchParts(parts: PartCatalogItem[]) {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request) => {
    let urlString: string
    if (typeof url === 'string') {
      urlString = url
    } else if (url instanceof URL) {
      urlString = url.toString()
    } else {
      urlString = url.url || url.toString()
    }

    if (urlString.includes('/api/parts')) {
      // Extract search param from URL - handle both absolute and relative URLs
      let search = ''
      try {
        const urlObj = new URL(urlString, 'http://localhost')
        search = urlObj.searchParams.get('search') || ''
      } catch {
        // Fallback for relative URLs that can't be parsed
        const match = urlString.match(/[?&]search=([^&]+)/)
        search = match ? decodeURIComponent(match[1]) : ''
      }

      // Filter parts by search term (case-insensitive name or exact barcode match)
      let filteredParts = parts.filter((part) => {
        if (!search.trim()) return true
        const lowerSearch = search.toLowerCase()
        return (
          part.name.toLowerCase().includes(lowerSearch) ||
          part.barcode === search
        )
      })

      // Sort alphabetically by name (matching backend behavior)
      filteredParts.sort((a, b) => a.name.localeCompare(b.name))

      return {
        ok: true,
        json: async () => ({ parts: filteredParts, total: filteredParts.length }),
      } as Response
    }
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

function mockFetchPartsError() {
  const mockFn = vi.fn().mockImplementation(async () => {
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

// ── Mock fetch for special product creation ────────────────────────

function mockFetchSpecialProduct(createdPart: PartCatalogItem) {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request, init?: RequestInit) => {
    if (url.toString().includes('/api/parts/special') && init?.method === 'POST') {
      return {
        ok: true,
        json: async () => createdPart,
      } as Response
    }
    // Fall through to parts search mock
    const urlString = url.toString()
    if (urlString.includes('/api/parts')) {
      return {
        ok: true,
        json: async () => ({ parts: [], total: 0 }),
      } as Response
    }
    return { ok: false } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

function mockFetchSpecialProductError() {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request, init?: RequestInit) => {
    if (url.toString().includes('/api/parts/special') && init?.method === 'POST') {
      return {
        ok: false,
        status: 400,
        json: async () => ({ error: 'Validation failed' }),
      } as Response
    }
    return { ok: true, json: async () => ({ parts: [], total: 0 }) } as Response
  })
  vi.stubGlobal('fetch', mockFn)
}

