import { describe, it, expect, vi, beforeEach, afterEach } from 'vitest'
import { render, screen, waitFor, act } from '@testing-library/react'
import { PosPage } from '../routes/PosPage'
import { useCartStore } from '../store'
import type { CustomerDetail } from '@/features/customers/types'

// ── Mock fetch ─────────────────────────────────────────────────────
//
// PosPage calls `GET /api/customers/:id` to populate the sidebar's
// customer cache. The list endpoint (`/api/customers`) is the compact
// shape and does NOT contain email/phone — only the detail endpoint does.

interface MockRoute {
  match: (url: string) => boolean
  respond: (url: string) => Promise<Response>
}

function mockFetchRoutes(routes: MockRoute[]) {
  const mockFn = vi.fn().mockImplementation(async (url: string | URL | Request) => {
    const urlString = url.toString()
    for (const route of routes) {
      if (route.match(urlString)) {
        return route.respond(urlString)
      }
    }
    return { ok: false, status: 404 } as Response
  })
  vi.stubGlobal('fetch', mockFn)
  return mockFn
}

/** Build a /api/customers/:id route that dispatches by id. */
function customerDetailRouteById(customers: Record<string, CustomerDetail | null>): MockRoute {
  return {
    match: (url) => /\/api\/customers\/[^/?]+$/.test(url),
    respond: async (url) => {
      const match = url.match(/\/api\/customers\/([^/?]+)$/)
      const id = match?.[1] ?? ''
      const customer = customers[id]
      if (!customer) {
        return {
          ok: false,
          status: 404,
          json: async () => ({ error: 'Customer not found' }),
        } as Response
      }
      return {
        ok: true,
        status: 200,
        json: async () => customer,
      } as Response
    },
  }
}

// ── Reset cart store ───────────────────────────────────────────────

function resetStore() {
  useCartStore.setState({
    lineItems: [],
    customerId: null,
    checkoutError: null,
    checkoutSuccess: null,
    isCheckingOut: false,
    subtotalNet: 0,
    vatTotal: 0,
    totalGross: 0,
    canCheckout: false,
  })
}

