import { useCallback, useEffect, useState } from 'react'
import type { PaymentMethod as PaymentMethodType } from '@shared/validations'
import { ShoppingCart, User } from 'lucide-react'
import { useCartStore } from '../store'
import { AddItemsSection } from '../components/AddItemsSection'
import { CartDisplay } from '../components/CartDisplay'
import { PosSection } from '../components/PosSection'
import { PosSidebar } from '../components/PosSidebar'
import { CustomerSelector } from '@/features/customers/components/CustomerSelector'
import type { CustomerDetail } from '@/features/customers/types'
import { PaymentDialog } from '../components/PaymentDialog'
import { submitCheckout, parseCheckoutSuccess } from '../services/checkout'

// ============================================================================
// Component — POS Page
// Premium dark layout:
//   • Left column: vertical stack of three glass sections
//       1. Customer (selector)
//       2. Add Items (search + barcode + special form)
//       3. Cart (line items table)
//   • Right sidebar: customer card + running totals + Pay button (sticky)
// ============================================================================

export function PosPage() {
  const customerId = useCartStore((s) => s.customerId)
  const setCustomer = useCartStore((s) => s.setCustomer)
  const startCheckout = useCartStore((s) => s.startCheckout)
  const finishCheckout = useCartStore((s) => s.finishCheckout)
  const failCheckout = useCartStore((s) => s.failCheckout)
  const getCheckoutPayload = useCartStore((s) => s.getCheckoutPayload)
  const lineItemCount = useCartStore((s) => s.lineItems.length)

  // Handle checkout submission
  const handleCheckout = useCallback(
    async (method: PaymentMethodType) => {
      startCheckout()

      try {
        const payload = getCheckoutPayload()
        // Override payment method from the form selection
        const checkoutPayload = { ...payload, paymentMethod: method }

        const response = await submitCheckout(checkoutPayload)
        const success = parseCheckoutSuccess(response)
        finishCheckout(success)
      } catch (err) {
        const message = err instanceof Error ? err.message : 'Unknown error during checkout'
        failCheckout(message)
      }
    },
    [startCheckout, finishCheckout, failCheckout, getCheckoutPayload]
  )

  const [paymentOpen, setPaymentOpen] = useState(false)

  // ── Cached selected customer (for sidebar display) ──
  // Fetches the FULL detail shape (email, phone, etc.) from GET /api/customers/:id.
  // The list endpoint returns the compact selector shape only.
  const [selectedCustomerCache, setSelectedCustomerCache] = useState<CustomerDetail | null>(null)

  useEffect(() => {
    if (!customerId) {
      setSelectedCustomerCache(null)
      return
    }

    let cancelled = false
    async function fetchCustomer() {
      try {
        const response = await fetch(`/api/customers/${encodeURIComponent(customerId!)}`)
        if (response.ok) {
          const data = (await response.json()) as CustomerDetail
          if (!cancelled) {
            setSelectedCustomerCache(data)
          }
        }
      } catch {
        // Silently fail
      }
    }
    fetchCustomer()
    return () => { cancelled = true }
  }, [customerId])

  return (
    <div className="dashboard-bg -m-6 min-h-full p-5 sm:p-7 lg:p-8">
      {/* Atmospheric glow orbs (subtle background motion) */}
      <div className="glow-orb glow-orb-cyan" aria-hidden />
      <div className="glow-orb glow-orb-violet" aria-hidden />


