  const subtotalNet = useCartStore((s) => s.subtotalNet)
  const vatTotal = useCartStore((s) => s.vatTotal)
  const totalGross = useCartStore((s) => s.totalGross)
  const canCheckout = useCartStore((s) => s.canCheckout)
  const itemCount = useCartStore((s) => s.lineItems.length)

  return (
    <aside className="w-80 shrink-0 hidden lg:flex flex-col gap-4 sticky top-4 self-start">
